/**
 * Councils with rules withheld because they apply to an area we have no outline of (OC-21).
 * Data: shared/not-covered-councils.json, generated by scripts/export_not_covered_councils.py
 * from data/chapter_scope/not_covered_2026-10-15.json. Per council, not per address.
 *
 * prior-art-checked: nearest is lib/dcp-land-application.ts (a per-property LEP gate); this is
 * a different, council-wide list.
 */
import notCoveredData from '@/shared/not-covered-councils.json';
import { councilKey } from '@/lib/council-key';
import { reasonText } from '@/lib/may-apply-reasons';

export interface NotCoveredChapter {
  chapter_key: string;
  /** The plan's own name for the part withheld (data/chapter_scope/not_covered_*.json `title`). */
  title?: string;
  reason: string;
  /** Why we cannot place it: a key of MAY_APPLY_REASONS. */
  reason_code?: string | null;
  /** The plain sentence for reason_code, or null when the code is missing or unknown. */
  reason_text?: string | null;
  /** Page in the chapter PDF where the land is described, when known. */
  page?: number | null;
}

export interface NotCovered {
  council: string;
  chapters: NotCoveredChapter[];
}

const DATA = notCoveredData as Record<string, Array<NotCoveredChapter & { count_hint?: number }>>;

/** The notice for the served council, or null when nothing is withheld for it. */
export function getNotCovered(formerCouncil: string | null | undefined): NotCovered | null {
  const slug = councilKey(formerCouncil);
  if (!slug) return null;
  const rows = Object.prototype.hasOwnProperty.call(DATA, slug) ? DATA[slug] : undefined;
  if (!rows || rows.length === 0) return null;
  return { council: slug, chapters: rows.map((r) => ({
      chapter_key: r.chapter_key,
      title: r.title,
      reason: r.reason,
      reason_code: r.reason_code ?? null,
      // Never a line without a reason: an unknown or missing code reads as the general one.
      reason_text: reasonText(r.reason_code) ?? reasonText('NOT_YET_MAPPED'),
      page: typeof r.page === 'number' ? r.page : null,
    })) };
}

/**
 * The notice without the chapters the may-apply block shows IN FULL for this suburb, so the page does not say "those
 * rules are not shown" beside a block that shows them (cross-review on #1411). A chapter is dropped only when one area
 * is the whole chapter: `areasInChapter` says it is the chapter's only area, and it loaded at least the chapter's
 * withheld count (count_hint). A chapter split over several areas (CB 7.3: 10, Warringah: 18), an area smaller than
 * its chapter (CB 2.2 flood: 1 of 97), or a failed or empty lookup keeps the chapter in the notice.
 */
export function withoutShownAreas(
  notCovered: NotCovered | null,
  mayApply: Array<{ chapter_key?: string; provisions?: unknown[] | null }>,
  areasInChapter: (chapterKey: string) => number,
): NotCovered | null {
  if (!notCovered) return null;
  const hints = new Map((DATA[notCovered.council] ?? []).map((r) => [r.chapter_key, r.count_hint]));
  const whole = new Set(
    mayApply
      .filter((a) => {
        const key = a.chapter_key;
        const hint = key ? hints.get(key) : undefined;
        return key && a.provisions && typeof hint === 'number' && areasInChapter(key) === 1 && a.provisions.length >= hint;
      })
      .map((a) => a.chapter_key as string),
  );
  const chapters = notCovered.chapters.filter((c) => !whole.has(c.chapter_key));
  return chapters.length > 0 ? { ...notCovered, chapters } : null;
}

/** "chapter-2-2-flood-risk-management" -> "Chapter 2 2 flood risk management". */
export function chapterLabel(key: string): string {
  const words = key.replace(/[-_]+/g, ' ').trim();
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : key;
}
